async function ensureMapSettings(){if(mapSettingsLoaded)return;const settings=await api('/api/settings');projectSettings.maps=settings.maps||{enabled:false,googleEmbedApiKey:''};mapSettingsLoaded=true}
function setRouteTab(tab){const mapEnabled=projectSettings.maps?.enabled===true,requested=['settings','clients','map'].includes(tab)?tab:'settings',valid=requested==='map'&&!mapEnabled?'clients':requested;document.querySelector('[data-route-tab="map"]').hidden=!mapEnabled;document.querySelectorAll('[data-route-tab]').forEach(button=>{const active=button.dataset.routeTab===valid;button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active))});document.querySelectorAll('[data-route-tab-panel]').forEach(panel=>{panel.hidden=panel.dataset.routeTabPanel!==valid});const next=$('[data-route-next]');if(next){next.hidden=valid==='clients'&&!mapEnabled;next.dataset.routeNext=valid==='settings'?'clients':valid==='clients'?'map':'clients';next.textContent=valid==='settings'?'Continuar para clientes →':valid==='clients'?'Continuar para trajeto →':'← Voltar para clientes'}if(valid==='map')renderRouteMapPreview()}
