function updateRouteFrequencyFields(){const frequency=$('#route-frequency').value,recurring=frequency!=='once';$('#route-end-date-wrap').hidden=!recurring;$('#route-weekdays-wrap').hidden=!recurring;$('#route-weeks-wrap').hidden=frequency!=='monthly';$('#route-end-date').min=$('#route-date').value;$('#route-end-date').required=false;if($('#route-end-date').value&&$('#route-end-date').value<$('#route-date').value)$('#route-end-date').value=$('#route-date').value}
