function setSettingsTab(name){const tab=document.querySelector(`[data-settings-tab="${name}"]`);if(!tab)return;document.querySelectorAll('[data-settings-tab]').forEach(button=>{const active=button===tab;button.classList.toggle('active',active);button.setAttribute('aria-selected',active?'true':'false');button.tabIndex=active?0:-1});document.querySelectorAll('[data-settings-panel]').forEach(panel=>{const active=panel.dataset.settingsPanel===name;panel.hidden=!active;panel.classList.toggle('active',active)});if(name==='access')renderUsers().catch(error=>showToast(error.message))}
document.addEventListener('click',event=>{const tab=event.target.closest('[data-settings-tab]');if(tab)setSettingsTab(tab.dataset.settingsTab)});
document.addEventListener('keydown',event=>{if(!event.target.matches('[data-settings-tab]')||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const tabs=[...document.querySelectorAll('[data-settings-tab]')],index=tabs.indexOf(event.target),next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(index+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[next].focus();tabs[next].click()});
