function setAuthMode(setup){authMode=setup?'setup':'login';$('#auth-name-wrap').hidden=!setup;$('#auth-name').required=setup;$('#auth-password').autocomplete=setup?'new-password':'current-password';$('#auth-password').minLength=setup?10:1;$('#auth-eyebrow').textContent=setup?'CONFIGURAÇÃO INICIAL':'ACESSO SEGURO';$('#auth-title').textContent=setup?'Criar acesso administrador':'Entre na sua conta';$('#auth-description').textContent=setup?'Crie o primeiro administrador para proteger e configurar os acessos ao sistema.':'Acesse sua operação comercial com seu e-mail e senha.';$('#auth-submit').textContent=setup?'Criar administrador':'Entrar';$('#auth-foot').textContent=setup?'O primeiro acesso recebe permissões de administrador.':'Acesso destinado a usuários autorizados.'}
function signedIn(user){currentUser=user;$('#app-shell').removeAttribute('inert');$('#auth-screen').classList.add('hidden');$('#profile-name').textContent=user.name;$('#profile-initials').textContent=initials(user.name);$('#top-avatar').textContent=initials(user.name);$('#profile-role').textContent=({admin:'Administrador',manager:'Gestor',seller:'Vendedor'})[user.role]||'Usuário';$('#settings-nav').hidden=user.role!=='admin';if(user.role!=='admin'&&$('#page-configuracoes').classList.contains('active'))go('inicio');liveUpdates?.close();liveUpdates=new EventSource('/api/events');liveUpdates.addEventListener('data-changed',async()=>{try{await refresh();if($('#page-relatorios').classList.contains('active'))await renderReports();if($('#page-configuracoes').classList.contains('active')&&document.querySelector('[data-settings-panel="access"]').classList.contains('active')&&currentUser?.role==='admin')await renderUsers();if($('#page-configuracoes').classList.contains('active')&&currentUser?.role==='admin')await loadProjectSettings();if(document.querySelector('#page-cliente-detalhe').classList.contains('active')&&currentCustomerId)renderCustomerDetail(currentCustomerId);if($('#page-rotas-visitas').classList.contains('active'))await renderVisitRoutes();if($('#page-rota-detalhe').classList.contains('active')&&currentVisitRouteId)await openVisitRoute(currentVisitRouteId)}catch(error){showToast(error.message)}});(async()=>{try{await loadProjectSettings()}catch(error){showToast(error.message)}await refresh().catch(error=>showToast(error.message))})()}
$('#auth-form').addEventListener('submit',async event=>{event.preventDefault();const button=$('#auth-submit');button.disabled=true;$('#auth-error').textContent='';try{const endpoint=authMode==='setup'?'/api/auth/setup':'/api/auth/login';const result=await api(endpoint,{method:'POST',body:JSON.stringify({name:$('#auth-name').value,email:$('#auth-email').value,password:$('#auth-password').value})});$('#auth-form').reset();signedIn(result.user)}catch(error){$('#auth-error').textContent=error.message}finally{button.disabled=false}});
$('#logout-btn').addEventListener('click',async()=>{try{await api('/api/auth/logout',{method:'POST'})}catch{}currentUser=null;liveUpdates?.close();$('#app-shell').setAttribute('inert','');$('#auth-password').value='';$('#auth-error').textContent='';setAuthMode(false);$('#auth-screen').classList.remove('hidden')});
document.addEventListener('click',async event=>{if(event.target.closest('[data-action="new-user"]'))$('#user-dialog').showModal();const toggle=event.target.closest('[data-user-id]');if(toggle){toggle.disabled=true;try{await api(`/api/users/${toggle.dataset.userId}/active`,{method:'PATCH',body:JSON.stringify({active:toggle.dataset.userActive==='1'})});await renderUsers();showToast('Acesso atualizado.')}catch(error){showToast(error.message)}finally{toggle.disabled=false}}if(event.target.id==='save-user'){event.preventDefault();const button=event.target;button.disabled=true;try{await api('/api/users',{method:'POST',body:JSON.stringify({name:$('#user-name').value,email:$('#user-email').value,password:$('#user-password').value,role:$('#user-role').value})});$('#user-dialog').close();$('#user-form').reset();await renderUsers();showToast('Acesso criado.')}catch(error){showToast(error.message)}finally{button.disabled=false}}});
async function initializeAuth(){try{const status=await api('/api/auth/status');if(status.setupRequired){setAuthMode(true);return}const result=await api('/api/auth/me');signedIn(result.user)}catch(error){setAuthMode(false);$('#auth-error').textContent='';$('#auth-screen').classList.remove('hidden')}}
