let systemTooltipTimer=null,systemTooltipTarget=null,systemTooltipNode=null;
function hideSystemTooltip(target){clearTimeout(systemTooltipTimer);if(target&&systemTooltipTarget&&target!==systemTooltipTarget)return;if(systemTooltipTarget)systemTooltipTarget.removeAttribute('aria-describedby');systemTooltipNode?.remove();systemTooltipNode=null;systemTooltipTarget=null}
function queueSystemTooltip(target){clearTimeout(systemTooltipTimer);systemTooltipTarget=target;systemTooltipTimer=setTimeout(()=>{if(!target.isConnected||!target.dataset.tooltip)return;const node=document.createElement('div');node.className='system-tooltip';node.id='system-tooltip';node.setAttribute('role','tooltip');node.textContent=target.dataset.tooltip;node.style.visibility='hidden';document.body.appendChild(node);const rect=target.getBoundingClientRect(),tip= node.getBoundingClientRect(),margin=10;let left=rect.left+rect.width/2-tip.width/2;left=Math.max(margin,Math.min(left,innerWidth-tip.width-margin));let top=rect.top-tip.height-9,nodeBelow=false;if(top<margin){top=rect.bottom+9;nodeBelow=true}node.style.left=left+'px';node.style.top=Math.min(top,innerHeight-tip.height-margin)+'px';node.classList.toggle('below',nodeBelow);node.style.visibility='';target.setAttribute('aria-describedby',node.id);systemTooltipNode=node},450)}
document.addEventListener('pointerover',event=>{if(event.pointerType!=='mouse')return;const target=event.target.closest('[data-tooltip]');if(target)queueSystemTooltip(target)});
document.addEventListener('pointerout',event=>{const target=event.target.closest('[data-tooltip]');if(target&&!target.contains(event.relatedTarget))hideSystemTooltip(target)});
document.addEventListener('focusin',event=>{const target=event.target.closest('[data-tooltip]');if(target)queueSystemTooltip(target)});
document.addEventListener('focusout',event=>{const target=event.target.closest('[data-tooltip]');if(target&&!target.contains(event.relatedTarget))hideSystemTooltip(target)});
